// FUNCTION: BFME2 0x000AA73A size=120 name=?getNameAndIndex@@YAPBDABVAsciiString@@PAH_N@Z evidence=N:ledger
const char *getNameAndIndex(const AsciiString &path, Int *index, Bool fullPath)
{
	// "...\\name12.ext": the frame number is the run of digits before the last
	// '.', and the name is either the whole path or what follows the last '\\'.
	const char *afterSlash = path.reverseFind('\\');
	if (afterSlash == NULL)
		return NULL;

	const char *number = path.reverseFind('.');
	if (number == NULL)
		return NULL;
	while (isdigit(number[-1]))
		--number;
	sscanf(number, "%d.", index);

	if (fullPath)
		return path.str();
	return afterSlash + 1;
}

// FUNCTION: BFME2 0x000AA7B2 size=137 name=?SetText@W3DAptDisplayString@@UAEXABVUnicodeString@@@Z evidence=N:ledger
void W3DAptDisplayString::SetText(const UnicodeString &text)
{
	const Bool unchanged = m_displayString->getText() == text;
	if (unchanged)
		return;

	m_displayString->setTargetSize(0.0f, 0.0f);
	m_displayString->setText(text);
	Int width;
	Int height;
	m_displayString->getSize(&width, &height);
	m_textWidth = static_cast<Real>(width);
	m_textHeight = static_cast<Real>(height);
}


